37	void read_data_sensor_data_file(const char          *file_path,
38	                                uint64_t            *ts_arr,
39	                                uint16_t             ts_len,
40	                                float               *data,
41	                                uint16_t             data_len,
42	                                void                *user_data,
43	                                sensor_data_callback callback) {
44	  LOGD(LOG_TAG, "Reading file: %s", file_path);
45	  FILE *fp;
46	  if ((fp = fopen(file_path, "r+")) == NULL) {
47	    LOGE(LOG_TAG, "Cannot open file: %s\n", file_path);
48	    exit(1);
49	  }
50	
51	  char  line[DEFAULT_LINE_LEN_MAX];
52	  char *pline;
53	
54	  // Read the header
55	  pline = fgets(line, DEFAULT_LINE_LEN_MAX, fp);
56	  if (pline == NULL) {
57	    return;
58	  }
59	
60	  while (feof(fp) == 0) {
61	    int cnt = 0;
62	    int param_num = 0;
63	    int total_read_num = 0;
64	
65	    // Read the ts
66	    while (cnt < ts_len) {
67	      param_num = fscanf(fp, "%lu", &ts_arr[cnt]);
68	      if (param_num != 1) {
69	        break;
70	      }
71	      ++cnt;
72	
73	      // Read the seperator
74	      fgetc(fp);
75	    }
76	    total_read_num += cnt;
77	
78	    // Read data
79	    cnt = 0;
80	    while (cnt < data_len) {
81	      param_num = fscanf(fp, "%f", &data[cnt]);
82	      if (param_num != 1) {
83	        break;
84	      }
85	      ++cnt;
86	      if (cnt < data_len) {
87	        // Read the seperator, but not read the '\n'
88	        fgetc(fp);
89	      }
90	    }
91	    total_read_num += cnt;
92	
93	    // Read the rest of the characters in one line.
94	    pline = fgets(line, DEFAULT_LINE_LEN_MAX, fp);
95	    if (pline == NULL) {
96	      LOGD(LOG_TAG, "File reached the end");
97	      break;
98	    }
99	    // LOGI(LOG_TAG, "param num: %d", total_read_num);
100	    if (total_read_num != (data_len + ts_len)) {
101	      LOGW(LOG_TAG,
102	           "Parse data num unexpected! %d != %d",
103	           total_read_num,
104	           (data_len + ts_len));
105	      continue;
106	    }
107	
108	    if (callback != NULL) {
109	      // LOGD(LOG_TAG, "Calling callback function");
110	      callback(ts_arr, ts_len, data, data_len, user_data);
111	    } else {
112	      LOGD(LOG_TAG, "Callback function is null");
113	    }
114	  }
115	
116	  fclose(fp);
117	}
