145	  if (last_counter != demo->res.counter) {
146	    // LOGD(LOG_TAG, "Real time Count: %d", demo->res.counter);
147	  }
148	  last_counter = demo->res.counter;
149	
150	  if (demo->res.freq > demo->max_freq) {
151	    demo->max_freq = demo->res.freq;
152	  }
